def specialFilter(nums):
    def is_odd_digit(digit):
        return digit in {1, 3, 5, 7, 9}

    def first_and_last_odd(n):
        n = abs(n)
        first_digit = n // 10**len(str(n))
        last_digit = n % 10
        return is_odd_digit(first_digit) and is_odd_digit(last_digit)

    return sum(1 for num in nums if num > 10 and first_and_last_odd(num))
