def cycpattern_check(a, b):
    if len(b) > len(a):
        return False
    for i in range(len(a) - len(b) + 1):
        if a[i:i+len(b)] == b or a[i:i+len(b)][::-1] == b:
            return True
        for j in range(1, len(b)):
            rotated = b[j:] + b[:j]
            if a[i:i+len(b)] == rotated or a[i:i+len(b)][::-1] == rotated:
                return True
    return False
