def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    max_unique = -1
    max_word = ""
    for word in words:
        count = unique_char_count(word)
        if count > max_unique or (count == max_unique and word < max_word):
            max_unique = count
            max_word = word
    return max_word
